function tokenize(s) {
  const toks = []
  let i = 0
  while (i < s.length) {
    const c = s[i]
    if (c === ' ' || c === '\t') { i++; continue }
    let m
    if ((m = /^[0-9]+(\.[0-9]+)?/.exec(s.slice(i)))) {
      toks.push({ k: 'num', v: Number(m[0]) }); i += m[0].length; continue
    }
    if ((m = /^[A-Za-z][A-Za-z0-9]*/.exec(s.slice(i)))) {
      toks.push({ k: 'word', v: m[0] }); i += m[0].length; continue
    }
    if ((m = /^(<>|<=|>=|[<>=+\-*/^(),:])/.exec(s.slice(i)))) {
      toks.push({ k: 'op', v: m[0] }); i += m[0].length; continue
    }
    return null
  }
  return toks
}

class Fail extends Error {}

export function parseFormula(body) {
  const toks = tokenize(body)
  if (!toks) return null
  let p = 0
  const peekOp = (v) => p < toks.length && toks[p].k === 'op' && toks[p].v === v
  const isCall = (i) => toks[i].k === 'word' && i + 1 < toks.length && toks[i + 1].k === 'op' && toks[i + 1].v === '('

  function comparison() {
    let l = additive()
    while (p < toks.length && toks[p].k === 'op' && ['=', '<>', '<', '<=', '>', '>='].includes(toks[p].v)) {
      const op = toks[p++].v
      l = { t: 'bin', op, l, r: additive() }
    }
    return l
  }
  function additive() {
    let l = term()
    while (peekOp('+') || peekOp('-')) {
      const op = toks[p++].v
      l = { t: 'bin', op, l, r: term() }
    }
    return l
  }
  function term() {
    let l = power()
    while (peekOp('*') || peekOp('/')) {
      const op = toks[p++].v
      l = { t: 'bin', op, l, r: power() }
    }
    return l
  }
  function power() {
    const l = unary()
    if (peekOp('^')) {
      p++
      return { t: 'bin', op: '^', l, r: power() }
    }
    return l
  }
  function unary() {
    if (peekOp('-') || peekOp('+')) {
      const op = toks[p++].v
      return { t: 'un', op, e: unary() }
    }
    return atom()
  }
  function atom() {
    if (p >= toks.length) throw new Fail()
    const tk = toks[p]
    if (tk.k === 'num') { p++; return { t: 'num', v: tk.v } }
    if (tk.k === 'op') {
      if (tk.v === '(') {
        p++
        const e = comparison()
        if (!peekOp(')')) throw new Fail()
        p++
        return { t: 'paren', e }
      }
      throw new Fail()
    }
    if (isCall(p)) {
      const name = tk.v.toUpperCase()
      p += 2
      const args = []
      if (peekOp(')')) { p++ } else {
        for (;;) {
          args.push(comparison())
          if (peekOp(',')) { p++; continue }
          if (peekOp(')')) { p++; break }
          throw new Fail()
        }
      }
      return { t: 'call', name, args }
    }
    p++
    const up = tk.v.toUpperCase()
    if (up === 'TRUE' || up === 'FALSE') return { t: 'bool', v: up === 'TRUE' }
    const ref = { t: 'ref', text: tk.v, addr: parseAddr(tk.v) }
    if (peekOp(':')) {
      p++
      if (p >= toks.length || toks[p].k !== 'word' || isCall(p)) throw new Fail()
      const t2 = toks[p++]
      const u2 = t2.v.toUpperCase()
