{"file_path":"src/eval.js","content":"import { parseFormula, cellAt } from './parse.js'

const ERRORS = ['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!']
const err = (v) => ({ t: 'e', v })
const num = (v) => ({ t: 'n', v })
const ZERO = num(0)

export function formatValue(v) {
  switch (v.t) {
    case 'n': return String(Number(v.v.toPrecision(10)))
    case 'b': return v.v ? 'TRUE' : 'FALSE'
    default: return v.v
  }
}

function rank(v) { return v.t === 'n' ? 0 : v.t === 's' ? 1 : 2 }

function cmpText(a, b) {
  const x = Array.from(a), y = Array.from(b)
  const n = Math.min(x.length, y.length)
  for (let i = 0; i < n; i++) {
    const d = x[i].codePointAt(0) - y[i].codePointAt(0)
    if (d) return d
  }
  return x.length - y.length
}

function compare(a, b) {
  const ra = rank(a), rb = rank(b)
  if (ra !== rb) return ra - rb
  if (a.t === 's') return cmpText(a.v, b.v)
  if (a.t === 'b') return Number(a.v) - Number(b.v)
  return a.v < b.v ? -1 : a.v > b.v ? 1 : 0
}

function toNum(v) {
  if (v.t === 'n') return v
  if (v.t === 'b') return num(v.v ? 1 : 0)
  if (v.t === 's') return err('#VALUE!')
  return v
}

function finite(v) {
  return Number.isFinite(v) ? num(v) : err('#DIV/0!')
}

export class Sheet {
  constructor(cells) {
    this.cells = cells
    this.memo = new Map()
    this.visiting = new Set()
  }

  get(key) {
    if (this.memo.has(key)) return this.memo.get(key)
    const cell = this.cells.get(key)
    if (!cell) return ZERO
    if (this.visiting.has(key)) return err('#CYCLE!')
    this.visiting.add(key)
    const v = this.compute(cell.content)
    this.visiting.delete(key)
    this.memo.set(key, v)
    return v
  }

  compute(content) {
    if (content[0] === '=') {
      const ast = parseFormula(content.slice(1))
      if (!ast) return err('#ERR!')
      return this.ev(ast)
    }
    if (content === '') return ZERO
    if (/^-?[0-9]+(\.[0-9]+)?$/.test(content)) return num(Number(content))
    if (ERRORS.includes(content)) return err(content)
    return { t: 's', v: content }
  }

  expand(n) {
    if (!n.a || !n.b) return [err('#REF!')]
    const c1 = Math.min(n.a.col, n.b.col), c2 = Math.max(n.a.col, n.b.col)
    const r1 = Math.min(n.a.row, n.b.row), r2 = Math.max(n.a.row, n.b.row)
    const out = []
    for (let c = c1; c <= c2; c++) for (let r = r1; r <= r2; r++) out.push(this.get(cellAt(c, r).key))
    return out
  }

  scalar(n) {
    if (n.t === 'range') {
      const vs = this.expand(n)
      const e = vs.find((v) => v.t === 'e')
      if (e) return e
      return vs.length === 1 ? vs[0] : err('#VALUE!')
    }
    return this.ev(n)
  }

  ev(n) {
    switch (n.t) {
      case 'num': return num(n.v)
      case 'bool': return { t: 'b', v: n.v }
      case 'paren': return this.ev(n.e)
      case 'ref': return n.addr ? this.get(n.addr.key) : err('#REF!')
      case 'range': return err('#ERR!')
      case 'un': {
        const v = toNum(this.ev(n.e))
        if (v.t === 'e') return v
        return num(n.op === '-' ? -v.v : v.v)
      }
      case 'bin': return this.bin(n)
      case 'call': return this.call(n)
    }
    return err('#ERR!')
  }

  bin(n) {
    const l = this.ev(n.l), r = this.ev(n.r)
    if (l.t === 'e') return l
    if (r.t === 'e') return r
    if (['=', '<>', '<', '<=', '>', '>='].includes(n.op)) {
      const c = compare(l, r)
      const res = { '=': c === 0, '<>': c !== 0, '<': c < 0, '<=': c <= 0, '>': c > 0, '>=': c >= 0 }[n.op]
      return { t: 'b', v: res }
    }
    const a = toNum(l)
    if (a.t === 'e') return a
    const b = toNum(r)
    if (b.t === 'e') return b
    switch (n.op) {
      case '+': return finite(a.v + b.v)
      case '-': return finite(a.v - b.v)
      case '*': return finite(a.v * b.v)
      case '/': return b.v === 0 ? err('#DIV/0!') : finite(a.v / b.v)
      case '^': return finite(Math.pow(a.v, b.v))
    }
    return err('#ERR!')
  }

  call(n) {
    const name = n.name
    const k = n.args.length
    const multi = ['SUM', 'MIN', 'MAX', 'COUNT', 'AVG']
    if (multi.includes(name)) {
      if (k < 1) return err('#ERR!')
      const vals = []
      for (const a of n.args) {
        if (a.t === 'range') vals.push(...this.expand(a))
        else vals.push(this.ev(a))
      }
      const e = vals.find((v) => v.t === 'e')
      if (e) return e
      if (name === 'COUNT') return num(vals.filter((v) => v.t === 'n').length)
      const nums = []
      for (const v of vals) {
        const x = toNum(v)
        if (x.t === 'e') return x
        nums.push(x.v)
      }
      if (name === 'SUM') return finite(nums.reduce((s, x) => s + x, 0))
      if (name === 'AVG') return finite(nums.reduce((s, x) => s + x, 0) / nums.length)
      if (name === 'MIN') return num(Math.min(...nums))
      return num(Math.max(...nums))
    }
    if (name === 'ABS') {
      if (k !== 1) return err('#ERR!')
      const v = toNum(this.scalar(n.args[0]))
      return v.t === 'e' ? v : num(Math.abs(v.v))
    }
    if (name === 'IF') {
      if (k !== 3) return err('#ERR!')
      const c = this.scalar(n.args[0])
      if (c.t === 'e') return c
      if (c.t === 's') return err('#VALUE!')
      const truth = c.t === 'b' ? c.v : c.v !== 0
      return this.scalar(n.args[truth ? 1 : 2])
    }
    return err('#NAME?')
  }
}
