import { readFileSync } from 'node:fs'
import { parseFormula, collectRefs } from './parse.js'
import { Sheet, formatValue } from './eval.js'
import { parseAddr } from './addr.js'

function fail(msg) {
  process.stderr.write(msg + '\n')
  process.exit(2)
}

const args = process.argv.slice(2)
if (args.length !== 1 || (args[0] !== 'values' && args[0] !== 'deps')) {
  fail('error: usage: cli.js values|deps')
}
const mode = args[0]

const lines = readFileSync(0, 'utf8').split('\n')
if (lines.length && lines[lines.length - 1] === '') lines.pop()

const cells = new Map()
for (let i = 0; i < lines.length; i++) {
  const s = lines[i].replace(/^[ \t]+/, '')
  if (s === '' || s[0] === '#') continue
  const raw = /^[^ \t]*/.exec(s)[0]
  const rest = s.slice(raw.length).replace(/^[ \t]+/, '')
  const a = parseAddr(raw)
  if (!a) fail(`error: line ${i + 1}: invalid cell address ${raw}`)
  if (cells.has(a.key)) fail(`error: line ${i + 1}: cell ${a.key} is declared twice`)
  cells.set(a.key, { addr: a, content: rest })
}

const sorted = [...cells.values()].sort((x, y) => x.addr.col - y.addr.col || x.addr.row - y.addr.row)
const out = []
if (mode === 'values') {
  const sheet = new Sheet(cells)
  for (const c of sorted) out.push(`${c.addr.key}=${formatValue(sheet.get(c.addr.key))}`)
} else {
  for (const c of sorted) {
    let names = []
    if (c.content[0] === '=') {
      const ast = parseFormula(c.content.slice(1))
      if (ast) {
        const set = new Map()
        collectRefs(ast, set)
        names = [...set.values()].sort((x, y) => x.col - y.col || x.row - y.row)
      }
    }
    out.push(`${c.addr.key}:` + names.map((n) => ' ' + n.key).join(''))
  }
}
process.stdout.write(out.map((l) => l + '\n').join(''))
